import {t} from './locales.js';
/** Presentation-only camera state, isolated per farm area and never serialized as simulation data. */
const views={field:{x:0,y:0,scale:1,rotation:0,panMode:false},chicken:{x:0,y:0,scale:1,rotation:0,panMode:false}};
/** @typedef {'field'|'chicken'} Area */
/** @param {Area} [area] */
export const cameraRotation=(area='field')=>views[area].rotation;
/** @param {Area} [area] */
export const cameraView=(area='field')=>({...views[area]});
const clamp=(/** @type {number} */n,/** @type {number} */min,/** @type {number} */max)=>Math.max(min,Math.min(max,n));
/** @param {number} id */
function select(id){document.dispatchEvent(new CustomEvent('plotselect',{detail:id}));}
/** @param {string} id */
function selectChicken(id){document.dispatchEvent(new CustomEvent('chickenobjectselect',{detail:id}));}
/** @param {HTMLElement} host @param {{area?:Area,redraw?:()=>void}} [options] */
export function bindCamera(host,{area='field',redraw=()=>{}}={}){
 const svg=/** @type {SVGSVGElement} */(host.querySelector('svg')),view=views[area];svg.setAttribute('role','group');svg.setAttribute('tabindex','0');
 function apply(){svg.querySelector('#map-camera')?.setAttribute('transform',`translate(${view.x} ${view.y}) translate(450 270) scale(${view.scale}) translate(-450 -270)`);svg.dataset.rotation=String(view.rotation);svg.style.touchAction=view.panMode?'none':'pan-y';host.querySelector('[data-camera=move]')?.setAttribute('aria-pressed',String(view.panMode));}
 /** @param {string} action */
 function change(action){let reproject=false;if(action==='reset'){reproject=view.rotation!==0;Object.assign(view,{x:0,y:0,scale:1,rotation:0,panMode:false});}else if(action==='left'||action==='right'){view.rotation=(view.rotation+(action==='right'?1:3))%4;reproject=true;}else if(action==='move')view.panMode=!view.panMode;else view.scale=clamp(Math.round((view.scale+(action==='in'?.15:-.15))*100)/100,.85,1.75);if(reproject){redraw();document.dispatchEvent(new Event('camerachanged'));/** @type {HTMLButtonElement|null} */(host.querySelector('[data-camera='+action+']'))?.focus({preventScroll:true});}else apply();}
 /** @type {{x:number,y:number,id:number,plot:number|null,object:string|null,market:boolean,moved:boolean}|null} */let start=null;
 svg.addEventListener('pointerdown',e=>{if(e.button!==0||!e.isPrimary)return;const target=/** @type {Element} */(e.target),plot=target.closest('[data-plot]');start={x:e.clientX,y:e.clientY,id:e.pointerId,plot:plot?Number(plot.getAttribute('data-plot')):null,object:target.closest('[data-chicken-object]')?.getAttribute('data-chicken-object')||null,market:!!target.closest('[data-facility="market"]'),moved:false};svg.setPointerCapture(e.pointerId);});
 svg.addEventListener('pointermove',e=>{if(!start||start.id!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>7||start.moved){start.moved=true;view.x=clamp(view.x+dx*900/svg.getBoundingClientRect().width,-180,180);view.y=clamp(view.y+dy*540/svg.getBoundingClientRect().height,-100,100);start.x=e.clientX;start.y=e.clientY;apply();}});
 svg.addEventListener('pointerup',e=>{if(!start||start.id!==e.pointerId)return;const s=start;start=null;if(!s.moved&&s.plot!==null)select(s.plot);if(!s.moved&&s.object)selectChicken(s.object);if(!s.moved&&s.market)document.dispatchEvent(new Event('marketopen'));if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);});svg.addEventListener('pointercancel',()=>{start=null;});
 svg.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();change(e.deltaY<0?'in':'out');},{passive:false});
 svg.addEventListener('keydown',e=>{if(e.target!==svg)return;const moves=/** @type {Record<string,number[]>} */({ArrowLeft:[-24,0],ArrowRight:[24,0],ArrowUp:[0,-18],ArrowDown:[0,18]});if(moves[e.key]){e.preventDefault();view.x=clamp(view.x+moves[e.key][0],-180,180);view.y=clamp(view.y+moves[e.key][1],-100,100);apply();}else{const shortcuts=/** @type {Record<string,string>} */({'[':'left',']':'right','+':'in','=':'in','-':'out','0':'reset',Home:'reset'});if(shortcuts[e.key]){e.preventDefault();change(shortcuts[e.key]);}}});
 const market=host.querySelector('[data-facility="market"]');if(market){market.setAttribute('role','button');market.setAttribute('tabindex','0');market.setAttribute('aria-label',t('marketTitle'));market.addEventListener('keydown',e=>{if(['Enter',' '].includes(/** @type {KeyboardEvent} */(e).key)){e.preventDefault();document.dispatchEvent(new Event('marketopen'));}});}
 host.querySelectorAll('[data-plot]').forEach(p=>{p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label',t('plot')+' '+(Number(p.getAttribute('data-plot'))+1));p.addEventListener('keydown',e=>{if(['Enter',' '].includes(/** @type {KeyboardEvent} */(e).key)){e.preventDefault();select(Number(p.getAttribute('data-plot')));}});});
 const objects=host.querySelectorAll('[data-chicken-object]');objects.forEach(p=>{p.setAttribute('tabindex','0');p.setAttribute('role','button');p.addEventListener('keydown',e=>{if(['Enter',' '].includes(/** @type {KeyboardEvent} */(e).key)){e.preventDefault();selectChicken(p.getAttribute('data-chicken-object')||'');}});});
 const controls=document.createElement('div');controls.className='camera-controls';controls.setAttribute('aria-label',t('viewControls'));
 for(const [label,key,action]of [['↶','rotateLeft','left'],['↷','rotateRight','right'],['−','zoomOut','out'],['+','zoomIn','in'],['↺','resetView','reset'],['↔','panView','move']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.title=t(key);b.setAttribute('aria-label',t(key));b.dataset.camera=action;if(action==='move')b.setAttribute('aria-pressed',String(view.panMode));b.addEventListener('click',()=>change(action));controls.append(b);}host.append(controls);
 const list=document.createElement('div');list.className='plot-shortcuts';list.setAttribute('aria-label',t('choosePlot'));host.querySelectorAll('[data-plot]').forEach(p=>{const id=Number(p.getAttribute('data-plot')),b=document.createElement('button');b.type='button';b.textContent=t('plot')+' '+(id+1);b.dataset.choosePlot=String(id);b.addEventListener('click',()=>select(id));list.append(b);});
 if(objects.length){list.classList.add('chicken-shortcuts');list.setAttribute('aria-label',t('chooseChickenObject'));objects.forEach(p=>{const id=p.getAttribute('data-chicken-object')||'',b=document.createElement('button');b.type='button';b.textContent=p.getAttribute('aria-label')||'';b.dataset.chooseChicken=id;b.addEventListener('click',()=>selectChicken(id));list.append(b);});}host.append(list);apply();
}
